export function getSubwayShopItemCost(def: SubwayShopItem): number {
    return def.cost;
}

export function computeSubwayBpReward(wins: number, isForfeit: boolean): number {
    if (isForfeit || wins < SUBWAY_BATTLES_PER_WAGON) return 0;
    return SUBWAY_REWARDS.bpPerRun;
}

