/**
 * @file src/lib/subwayShopSnapshot.ts
 * Read-only snapshot for Battle Subway shop offers.
 */

import type { GameRuntime } from '../types/game.js';
import type { SubwayShopOfferSnapshot } from '../bus/snapshots.js';
import {
    SUBWAY_SHOP_ITEMS,
    getSubwayShopItemCost,
    type SubwayShopItem,
} from '../../constants/balance/subwayRewards.ts';
import { HELD_ITEMS } from '../../constants/balance/towerAndItems.ts';
import { getAllItem } from '../ui/uiItems.ts';
import { getItemIconHTML } from '../ui/utils.ts';

function subwayT(game: GameRuntime, key: string, fallback: string, vars: Record<string, string | number> = {}): string {
    let out = fallback;
    if (typeof game.t === 'function') {
        const translated = game.t(key);
        if (translated && translated !== key) out = translated;
    }
    for (const [k, v] of Object.entries(vars)) {
        out = out.replace(new RegExp(`\\{${k}\\}`, 'g'), String(v));
    }
    return out;
}

function resolveItemIcon(def: SubwayShopItem): string {
    const held = (HELD_ITEMS as Record<string, { img?: string; name?: string; icon?: string }>)[def.itemKey];
    if (held) return getItemIconHTML(held) || '';
    const item = getAllItem(def.itemKey);
    if (item) return getItemIconHTML(item) || '';
    return '';
}

function buildOffer(game: GameRuntime, def: SubwayShopItem, lang: 'fr' | 'en'): SubwayShopOfferSnapshot {
    const purchases = game.subwayShopPurchases ?? {};
    const bought = Number(purchases[def.id] ?? 0);

    let purchasesRemaining: number | null = null;
    let isSoldOut = false;
    if (def.maxPurchases != null) {
        purchasesRemaining = Math.max(0, def.maxPurchases - bought);
        isSoldOut = purchasesRemaining <= 0;
    }

    const cost = getSubwayShopItemCost(def);
    const canAfford = !isSoldOut && (game.subwayBP ?? 0) >= cost;
    const canBuy = canAfford && !isSoldOut;

    let stockLabel: string | null = null;
    if (def.maxPurchases != null) {
        stockLabel = subwayT(
            game,
            'subway.shopStockRemaining',
            'Stock : {remaining}/{max}',
            { remaining: purchasesRemaining ?? 0, max: def.maxPurchases },
        );
    }

    const buttonLabel = isSoldOut
        ? subwayT(game, 'subway.shopSoldOut', 'Épuisé')
        : (canAfford
            ? subwayT(game, 'subway.shopBuy', 'Acheter')
            : subwayT(game, 'subway.shopInsufficientBp', 'BP insuffisants'));

    return {
        id: def.id,
        displayName: def.name[lang],
        description: def.description[lang],
        iconHtml: resolveItemIcon(def),
        cost,
        costFormatted: isSoldOut ? 'MAX' : String(cost),
        canBuy,
        isSoldOut,
        stockLabel,
        buttonLabel,
        exclusive: !!def.exclusive,
    };
}

export function buildSubwayShopOffersSnapshot(game: GameRuntime): SubwayShopOfferSnapshot[] {
    if (!game.unlockedFeatures?.subwayTab) return [];
    const lang = game.normalizeLanguage?.(game.language) === 'en' ? 'en' : 'fr';

    const offers = SUBWAY_SHOP_ITEMS.map((def) => buildOffer(game, def, lang));

    offers.sort((a, b) => {
        const defA = SUBWAY_SHOP_ITEMS.find((d) => d.id === a.id);
        const defB = SUBWAY_SHOP_ITEMS.find((d) => d.id === b.id);
        const orderA = defA?.sortOrder ?? 0;
        const orderB = defB?.sortOrder ?? 0;
        if (orderA !== orderB) return orderA - orderB;
        if (a.isSoldOut !== b.isSoldOut) return a.isSoldOut ? 1 : -1;
        return 0;
    });

    return offers;
}

export function buildSubwayShopDesc(game: GameRuntime): string {
    return subwayT(
        game,
        'subway.shopDesc',
        'Sept objets tenus exclusifs au Battle Subway — introuvables ailleurs.',
    );
}
