/**
 * @file src/lib/shopSnapshot.ts
 * Read-only snapshot for ShopPanel Svelte sub-tabs.
 */

import type { GameRuntime } from '../types/game.js';
import type { ShopPanelUiSnapshot, ShopSnapshot } from '../bus/snapshots.js';
import { publish } from '../bus/pub.js';
import { GameEventType as Evt } from '../bus/events.js';
import {
  pickShopMart,
  shopMartTimerWouldChange,
  shopMartWouldChange,
  shopSnapshotWouldChange,
} from '../stores/shopSnapshotDiff.js';
import type { ShopMartSnapshot } from '../bus/snapshots.js';
import {
  buildMartHtml,
  buildMartOffersSnapshot,
  buildMartMoneyText,
  buildMartTimerSnapshot,
  buildUpgradesHtml,
  buildTokenShopHtml,
  buildQuestTokensText,
  buildTowerShopHtml,
  buildRecyclerSnapshot,
} from '@snapshot/shop';
import { buildMartAutoPurchaseButtonLabel } from './martAutoPurchaseSnapshot.ts';
import { buildSubwayShopOffersSnapshot, buildSubwayShopDesc } from './subwayShopSnapshot.ts';

function shopT(game: GameRuntime, key: string, fallback: string): string {
  if (typeof game.t === 'function') {
    const translated = game.t(key);
    if (translated && translated !== key) return translated;
  }
  return fallback;
}

export function buildShopPanelUi(game: GameRuntime): ShopPanelUiSnapshot {
  const language =
    game && typeof game.normalizeLanguage === 'function'
      ? game.normalizeLanguage(game.language)
      : 'fr';
  return {
    language,
    subTabsAriaLabel: shopT(game, 'shop.subTabsAriaLabel', 'Sous-sections boutique'),
    subGrocery: shopT(game, 'shop.subGrocery', 'Epicerie'),
    subUpgrades: shopT(game, 'shop.subUpgrades', 'Améliorations'),
    subTokens: shopT(game, 'shop.subTokens', 'Boutique Jetons'),
    subTower: shopT(game, 'shop.subTower', 'Boutique Tour'),
    subSubway: shopT(game, 'shop.subSubway', 'Boutique Subway'),
    subRecycler: shopT(game, 'shop.subRecycler', 'Recycleur'),
    martTitle: shopT(game, 'shop.martTitle', 'PokeMart'),
    walletLabel: shopT(game, 'shop.wallet', 'Porte-monnaie :'),
    upgradesTitle: shopT(game, 'shop.upgradesTitle', 'Améliorations'),
    specialTitle: shopT(game, 'shop.specialTitle', 'Boutique Spéciale'),
    tokensUnit: shopT(game, 'shop.tokensUnit', 'Jetons'),
    towerTitle: shopT(game, 'shop.towerTitle', 'Boutique de la Tour'),
    towerDesc: shopT(
      game,
      'shop.towerDesc',
      'Utilisez vos Marques du Triomphe pour acheter des améliorations uniques.',
    ),
    subwayTitle: shopT(game, 'shop.subwayTitle', 'Boutique Subway'),
    subwayDesc: shopT(
      game,
      'shop.subwayDesc',
      'Trois objets tenus exclusifs au Battle Subway — introuvables ailleurs.',
    ),
    subwayBpLabel: shopT(game, 'shop.subwayBpLabel', 'Points Subway :'),
    recyclerTotal: shopT(game, 'shop.recyclerTotal', 'Total :'),
    recyclerEssenceLabel: shopT(game, 'shop.essenceDustLabel', "Poussière d'essence"),
    recyclerShardsTitle: shopT(game, 'shop.recyclerShardsTitle', 'Vos Shards'),
    recyclerDustShopTitle: shopT(game, 'shop.recyclerDustShopTitle', 'Boutique de Poussière'),
    recyclerSearchPlaceholder: shopT(game, 'shop.recyclerSearchPlaceholder', 'Rechercher une famille...'),
    recyclerSortRarity: shopT(game, 'shop.recyclerSortRarity', 'Rareté'),
    recyclerSortCount: shopT(game, 'shop.recyclerSortCount', 'Quantité'),
  };
}

function withShopUi(game: GameRuntime, snap: Omit<ShopSnapshot, 'ui'> & Partial<Pick<ShopSnapshot, 'ui'>>): ShopSnapshot {
  return { ...snap, ui: buildShopPanelUi(game) } as ShopSnapshot;
}

export function buildShopSnapshot(game: GameRuntime): ShopSnapshot {
  const timer = buildMartTimerSnapshot(game);
  const recycler = buildRecyclerSnapshot(game);
  const martOffers = buildMartOffersSnapshot(game);
  return withShopUi(game, {
    martHtml: buildMartHtml(game) ?? '',
    martMoney: buildMartMoneyText(game),
    martOfferTimer: String(timer.text ?? ''),
    martOfferTimerLabel: String(timer.label ?? ''),
    autoPurchaseButtonLabel: buildMartAutoPurchaseButtonLabel(game),
    offers: martOffers.offers,
    martEmptyMessage: martOffers.martEmptyMessage,
    upgradesHtml: buildUpgradesHtml(game) ?? '',
    tokenShopHtml: buildTokenShopHtml(game) ?? '',
    questTokens: buildQuestTokensText(game),
    towerShopHtml: buildTowerShopHtml(game) ?? '',
    subwayShopVisible: !!game.unlockedFeatures?.subwayTab,
    subwayShopOffers: buildSubwayShopOffersSnapshot(game),
    subwayShopDesc: buildSubwayShopDesc(game),
    subwayBP: String(game.subwayBP ?? 0),
    recyclerShards: recycler.recyclerShards,
    recyclerDustOffers: recycler.recyclerDustOffers,
    recyclerShardsEmpty: recycler.recyclerShardsEmpty,
    essenceDust: recycler.essenceDust,
    recyclerSortRarityActive: recycler.recyclerSortRarityActive,
    recyclerSortCountActive: recycler.recyclerSortCountActive,
  });
}

let lastShopSnapshot: ShopSnapshot | null = null;
let lastShopMart: ShopMartSnapshot | null = null;

/** @internal Vitest only */
export function resetShopSnapshotDedupForTests(): void {
  lastShopSnapshot = null;
  lastShopMart = null;
}

/** Build snapshot and publish SHOP_CHANGED (deduped). */
export function notifyShopChanged(game: GameRuntime): void {
  const shop = buildShopSnapshot(game);
  if (lastShopSnapshot && !shopSnapshotWouldChange(lastShopSnapshot, shop)) return;
  lastShopSnapshot = shop;
  lastShopMart = pickShopMart(shop);
  publish({ type: Evt.SHOP_CHANGED, shop });
}

/** Mart timer tick — does not replace martHtml in store. */
export function notifyShopMartTimerChanged(game: GameRuntime): void {
  const timer = buildMartTimerSnapshot(game);
  const mart: ShopMartSnapshot = {
    martHtml: lastShopMart?.martHtml ?? '',
    martMoney: lastShopMart?.martMoney ?? buildMartMoneyText(game),
    martOfferTimer: String(timer.text ?? ''),
    martOfferTimerLabel: String(timer.label ?? ''),
    autoPurchaseButtonLabel: lastShopMart?.autoPurchaseButtonLabel ?? buildMartAutoPurchaseButtonLabel(game),
    offers: lastShopMart?.offers ?? [],
    martEmptyMessage: lastShopMart?.martEmptyMessage ?? null,
  };
  if (lastShopMart && !shopMartTimerWouldChange(lastShopMart, mart)) return;
  lastShopMart = mart;
  if (lastShopSnapshot) {
    lastShopSnapshot = withShopUi(game, { ...lastShopSnapshot, ...mart });
  } else {
    lastShopSnapshot = withShopUi(game, {
      martHtml: '',
      martMoney: mart.martMoney,
      martOfferTimer: mart.martOfferTimer,
      martOfferTimerLabel: mart.martOfferTimerLabel,
      autoPurchaseButtonLabel: mart.autoPurchaseButtonLabel,
      offers: [],
      martEmptyMessage: null,
      upgradesHtml: '',
      tokenShopHtml: '',
      questTokens: '',
      towerShopHtml: '',
      subwayShopVisible: false,
      subwayShopOffers: [],
      subwayShopDesc: '',
      subwayBP: '0',
      recyclerShards: [],
      recyclerDustOffers: [],
      recyclerShardsEmpty: null,
      essenceDust: '0',
      recyclerSortRarityActive: false,
      recyclerSortCountActive: false,
    });
  }
  if (lastShopSnapshot) {
    publish({ type: Evt.SHOP_CHANGED, shop: lastShopSnapshot });
  }
}

/** Mart offers / wallet — updates martHtml without touching other shop tabs. */
export function notifyShopMartChanged(game: GameRuntime): void {
  const shop = buildShopSnapshot(game);
  const mart = pickShopMart(shop);
  if (lastShopMart && !shopMartWouldChange(lastShopMart, mart)) return;
  lastShopMart = mart;
  if (lastShopSnapshot) {
    lastShopSnapshot = withShopUi(game, { ...lastShopSnapshot, ...mart });
  } else {
    lastShopSnapshot = shop;
  }
  publish({ type: Evt.SHOP_CHANGED, shop: lastShopSnapshot });
}
